<script setup lang="ts">
import { reactive, watch } from 'vue'
import { buildRegistryPayload, draftForRegistry, type RegistryKind } from '../lib/registryForms'
const props=defineProps<{kind:RegistryKind;record?:Record<string,any>|null;assets:Record<string,any>[];segments:Record<string,any>[];busy:boolean;publicData?:boolean}>()
const emit=defineEmits<{submit:[Record<string,unknown>];cancel:[]}>()
const draft=reactive<Record<string,string>>({}), errors=reactive<Record<string,string>>({})
function reset(){Object.keys(draft).forEach(k=>delete draft[k]);Object.assign(draft,draftForRegistry(props.kind,props.record||undefined));if(props.publicData&&props.kind==='assets'){draft.synthetic='false';draft.condition='unknown';if(!props.record)draft.type='other'}Object.keys(errors).forEach(k=>delete errors[k])}
watch(()=>[props.kind,props.record,props.publicData] as const,reset,{immediate:true,deep:true})
function submit(){Object.keys(errors).forEach(k=>delete errors[k]);const result=buildRegistryPayload(props.kind,draft,props.record||undefined);if(!result.ok){Object.assign(errors,result.errors);return}emit('submit',result.payload)}
</script>
<template>
<form class="registry-form" @submit.prevent="submit">
  <p v-if="kind==='observations'" class="warning">Спостереження додаються на сторінці «Спостереження». Тут їх не можна змінювати, щоб не обійти внесення часу, доказів і рецензування.</p>
  <template v-else>
    <template v-if="kind==='assets'"><label>Назва<input name="name" v-model="draft.name" required></label><label>Тип<select v-model="draft.type"><option value="well">Свердловина</option><option value="site">Майданчик</option><option value="other">Інше</option></select></label><label>Стан<select v-model="draft.condition" :disabled="publicData"><option value="unknown">Невідомо</option><option value="less_adverse">Менш несприятливий</option><option value="adverse">Несприятливий</option><option value="severe">Суттєве перезволоження</option></select></label><label>Посилання на джерело<input v-model="draft.source_ref"></label><label>Синтетичний запис<select v-model="draft.synthetic" :disabled="publicData"><option value="true">Так</option><option value="false">Ні</option></select></label></template>
    <template v-else-if="kind==='segments'"><label>Об’єкт<select v-model="draft.asset_id" required><option value="">Оберіть об’єкт</option><option v-for="a in assets" :key="a.id" :value="a.id">{{a.id}} — {{a.name}}</option></select></label><label>Довжина, м<input v-model="draft.length_m" type="number" min="0" step="0.1" required></label><small v-if="errors.length_m" class="field-error">{{errors.length_m}}</small><label>Покриття<input v-model="draft.surface"></label><label>Конструкція<select v-model="draft.construction"><option value="unknown">Невідомо</option><option value="known">Відомо</option></select></label><label>Дренаж<select v-model="draft.drainage"><option value="unknown">Невідомо</option><option value="present">Наявний</option><option value="absent">Відсутній</option></select></label><label>Водопропуск<select v-model="draft.culvert_status"><option value="unknown">Невідомо</option><option value="present">Наявний</option><option value="absent">Відсутній</option></select></label></template>
    <template v-else-if="kind==='protocols'"><label>Назва<input name="name" v-model="draft.name" required></label><label>Метод<input v-model="draft.method" required></label><label>Одиниця<input v-model="draft.unit" required></label><label>Обов’язкові поля <small>через кому</small><input v-model="draft.requiredFieldsText" placeholder="observed_at, value"></label></template>
    <template v-else-if="kind==='models'"><p class="warning">Лише метадані реєстру: ця форма не калібрує, не затверджує модель і не робить її придатною для виробництва.</p><label>Назва<input v-model="draft.name" required></label><label>Статус<select v-model="draft.status"><option value="research">Дослідницька</option><option value="blocked">Заблокована</option></select></label><label>Область застосування<textarea v-model="draft.scope"></textarea></label><label>Посилання на картку<input v-model="draft.card_ref"></label><label>Причина / межі<textarea v-model="draft.reason"></textarea></label></template>
    <template v-else-if="kind==='envelopes'"><p class="warning">Лише метадані реєстру: параметри транспортної межі не обчислюються та не затверджуються цією формою.</p><label>Назва<input v-model="draft.name" required></label><label>Область застосування<textarea v-model="draft.scope"></textarea></label><label>Причина / примітка<textarea v-model="draft.reason"></textarea></label></template>
    <template v-else-if="kind==='constraints'"><label>Об’єкт<select v-model="draft.asset_id"><option value="">Не вибрано</option><option v-for="a in assets" :key="a.id" :value="a.id">{{a.id}} — {{a.name}}</option></select></label><label>Ділянка<select v-model="draft.segment_id"><option value="">Не вибрано</option><option v-for="s in segments" :key="s.id" :value="s.id">{{s.id}}</option></select></label><label>Тип<input v-model="draft.kind" required></label><label>Стан<select v-model="draft.status"><option value="unknown">Невідомо</option><option value="open">Відкрито</option><option value="closed">Закрито</option></select></label><label>Причина<textarea v-model="draft.reason"></textarea></label></template>
    <template v-else-if="kind==='tickets'"><label>Об’єкт<select v-model="draft.asset_id"><option value="">Не вибрано</option><option v-for="a in assets" :key="a.id" :value="a.id">{{a.id}} — {{a.name}}</option></select></label><label>Ділянка<select v-model="draft.segment_id"><option value="">Не вибрано</option><option v-for="s in segments" :key="s.id" :value="s.id">{{s.id}}</option></select></label><label>Назва<input v-model="draft.title" required></label><label>Стан<select v-model="draft.status"><option value="open">Відкрита</option><option value="requested">Запит створено</option><option value="closed">Закрита</option></select></label><label>Причина<textarea v-model="draft.reason"></textarea></label><label>Термін (UTC)<input v-model="draft.due_at" type="datetime-local" step="0.001"></label><small v-if="errors.due_at" class="field-error">{{errors.due_at}}</small></template>
    <template v-else-if="kind==='subscriptions'"><p class="warning">Доставка повідомлень не налаштована: підписка є лише метаданими і не надсилає повідомлення.</p><label>Об’єкт<select v-model="draft.asset_id"><option value="">Не вибрано</option><option v-for="a in assets" :key="a.id" :value="a.id">{{a.id}} — {{a.name}}</option></select></label><label>Ділянка<select v-model="draft.segment_id"><option value="">Не вибрано</option><option v-for="s in segments" :key="s.id" :value="s.id">{{s.id}}</option></select></label><label>Канал<select v-model="draft.channel"><option value="in_app">У застосунку</option><option value="email">Електронна пошта</option></select></label><label>Стан<select v-model="draft.status"><option value="active">Активна</option><option value="paused">Призупинена</option></select></label><label>Примітка<textarea v-model="draft.note"></textarea></label></template>
    <template v-else-if="kind==='inspections'"><label>Об’єкт<select v-model="draft.asset_id"><option value="">Не вибрано</option><option v-for="a in assets" :key="a.id" :value="a.id">{{a.id}} — {{a.name}}</option></select></label><label>Ділянка<select v-model="draft.segment_id"><option value="">Не вибрано</option><option v-for="s in segments" :key="s.id" :value="s.id">{{s.id}}</option></select></label><label>Стан<select v-model="draft.status"><option value="requested">Запит створено</option><option value="scheduled">Заплановано</option><option value="complete">Завершено</option></select></label><label>Причина<textarea v-model="draft.reason" required></textarea></label><label>Запланований час (UTC)<input v-model="draft.scheduled_at" type="datetime-local" step="0.001"></label><small v-if="errors.scheduled_at" class="field-error">{{errors.scheduled_at}}</small></template>
    <details v-if="kind==='assets'||kind==='segments'"><summary>Розширено: геометрія JSON</summary><label>GeoJSON geometry<textarea v-model="draft.geometryText" rows="5" aria-describedby="geometry-error"></textarea></label><small id="geometry-error" v-if="errors.geometryText" class="field-error">{{errors.geometryText}}</small></details>
    <small v-if="errors.form" class="field-error">{{errors.form}}</small>
    <div class="form-actions"><button class="primary" :disabled="busy">{{record?'Зберегти зміни':'Створити запис'}}</button><button type="button" :disabled="busy" @click="emit('cancel')">Скасувати</button></div>
  </template>
  <button v-if="kind==='observations'" type="button" @click="emit('cancel')">Закрити</button>
</form>
</template>
